// All money math is done in integer cents to avoid IEEE-754 float drift.
// Never multiply a price by 100 as a float (e.g. 4.35 * 100 === 434.99999999999994).

const PRICE_RE = /^-?(\d+)(?:\.(\d{1,2}))?$/;

/**
 * Safely convert a price string like "4.35" or "0.1" into integer cents.
 * Pure string/digit parsing -- no float multiplication anywhere.
 * Throws on malformed input ("abc") or >2 decimal places ("4.355").
 */
function parsePriceToCents(str) {
  if (typeof str !== 'string') throw new TypeError(`price must be a string, got ${typeof str}`);
  const m = PRICE_RE.exec(str.trim());
  if (!m) throw new SyntaxError(`invalid price: "${str}"`);
  const sign = str.trim().startsWith('-') ? -1 : 1;
  const dollars = m[1];
  const frac = (m[2] || '').padEnd(2, '0'); // "4.3" -> "30"
  return sign * (Number(dollars) * 100 + Number(frac));
}

/**
 * Sum item quantities in integer cents.
 * items: [{priceDollars: "4.35", qty: number}] -> total cents
 */
function cartTotal(items) {
  let total = 0;
  for (const it of items) total += parsePriceToCents(it.priceDollars) * it.qty;
  return total;
}

/** Format integer cents as a plain decimal string, e.g. 435 -> "435.00". */
function formatCents(cents) {
  if (!Number.isInteger(cents)) throw new TypeError('cents must be an integer');
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  return `${sign}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

function equalTotals(a, b) {
  return a === b; // exact on integers
}

module.exports = { cartTotal, equalTotals, parsePriceToCents, formatCents };
"})
