result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/cart.test.js", "content": "const test = require('node:test');
const assert = require('node:assert');
const { cartTotal, equalTotals, parsePriceToCents, formatCents } = require('./cart.js');

test('0.1 + 0.2 equals 30 cents exactly', () => {
  const t = cartTotal([{ priceDollars: '0.1', qty: 1 }, { priceDollars: '0.2', qty: 1 }]);
  assert.ok(equalTotals(t, parsePriceToCents('0.3')));
  assert.equal(t, 30);
});

test('4.35 * 100 equals 435 cents exactly', () => {
  const t = cartTotal([{ priceDollars: '4.35', qty: 100 }]);
  assert.ok(equalTotals(t, 435));
  assert.equal(formatCents(t), '435.00');
});

test('100k-item stress total is exact', () => {
  const items = Array.from({ length: 100_000 }, () => ({ priceDollars: '19.99', qty: 3 }));
  assert.equal(cartTotal(items), 19_99 * 3 * 100_000); // 5,997,000 cents
});

test('parsePriceToCents basics and formatting', () => {
  assert.equal(parsePriceToCents('4.35'), 435);
  assert.equal(parsePriceToCents('0.1'), 10);
  assert.equal(parsePriceToCents('7'), 700);
  assert.equal(formatCents(5997000), '59970.00');
  assert.equal(formatCents(-105), '-1.05');
});

test('parse rejects malformed prices', () => {
  assert.throws(() => parsePriceToCents('4.355')); // > 2 decimals
  assert.throws(() => parsePriceToCents('abc'));
});
"})
